-- Expand the status check constraint to support the full onboarding lifecycle
ALTER TABLE executive_appointments DROP CONSTRAINT executive_appointments_status_check;
ALTER TABLE executive_appointments ADD CONSTRAINT executive_appointments_status_check 
  CHECK (status = ANY (ARRAY['pending', 'approved', 'active', 'terminated', 'documents_sent', 'documents_generated', 'signing_in_progress', 'partially_signed', 'fully_signed', 'authorized_to_offer', 'offer_accepted']));

